mapper.select:
SELECT id, name, code, status, remark, creator, create_time, updater, update_time, deleted, tenant_id
FROM equipment_device
WHERE deleted = 0

    AND name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND status = #{reqVO.status}


    AND create_time BETWEEN #{reqVO.createTime[0],javaType=java.time.LocalDateTime}
                        AND #{reqVO.createTime[1],javaType=java.time.LocalDateTime}

ORDER BY id DESC
